-- 1. ENSURE DEFAULT UUID FOR MISSING IDs
ALTER TABLE public.workflow_department_settings ALTER COLUMN id SET DEFAULT gen_random_uuid()::text;
UPDATE public.workflow_department_settings SET id = department_id WHERE id IS NULL;

-- 2. CLEANUP NULL IDs AND EXISTING DUPLICATES
DELETE FROM public.orders WHERE id IS NULL;
DELETE FROM public.orders a USING public.orders b WHERE a.ctid < b.ctid AND a.id = b.id;
DELETE FROM public.order_items WHERE id IS NULL;
DELETE FROM public.order_items a USING public.order_items b WHERE a.ctid < b.ctid AND a.id = b.id;
DELETE FROM public.profiles WHERE id IS NULL;
DELETE FROM public.profiles a USING public.profiles b WHERE a.ctid < b.ctid AND a.id = b.id;
DELETE FROM public.tax_templates WHERE id IS NULL;
DELETE FROM public.tax_templates a USING public.tax_templates b WHERE a.ctid < b.ctid AND a.id = b.id;
DELETE FROM public.workflow_departments WHERE id IS NULL;
DELETE FROM public.workflow_departments a USING public.workflow_departments b WHERE a.ctid < b.ctid AND a.id = b.id;
DELETE FROM public.workflow_department_settings WHERE id IS NULL;
DELETE FROM public.workflow_department_settings a USING public.workflow_department_settings b WHERE a.ctid < b.ctid AND a.id = b.id;
DELETE FROM public.workflow_stage_history WHERE id IS NULL;
DELETE FROM public.workflow_stage_history a USING public.workflow_stage_history b WHERE a.ctid < b.ctid AND a.id = b.id;

-- 3. ENSURE PRIMARY KEYS EXIST
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_pkey') THEN
    ALTER TABLE public.orders ADD PRIMARY KEY (id);
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'order_items_pkey') THEN
    ALTER TABLE public.order_items ADD PRIMARY KEY (id);
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'profiles_pkey') THEN
    ALTER TABLE public.profiles ADD PRIMARY KEY (id);
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'tax_templates_pkey') THEN
    ALTER TABLE public.tax_templates ADD PRIMARY KEY (id);
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'workflow_departments_pkey') THEN
    ALTER TABLE public.workflow_departments ADD PRIMARY KEY (id);
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'workflow_department_settings_pkey') THEN
    ALTER TABLE public.workflow_department_settings ADD PRIMARY KEY (id);
  END IF;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'workflow_stage_history_pkey') THEN
    ALTER TABLE public.workflow_stage_history ADD PRIMARY KEY (id);
  END IF;
END $$;

